insert into public.products (name, brand, benefit_fr, benefit_en, usage_fr, usage_en, price, hair_types, scalp_types, for_beard, effects, sort, active) values ('01 Bubble Gum', 'Nishman', 'Cire à base d’eau au parfum bubble gum : brillance et coiffage facile, se rince sans effort.', 'Water based wax with a bubble gum scent: shine and easy styling, rinses out effortlessly.', 'Une noisette sur cheveux secs ou légèrement humides, coiffer au peigne ou avec les doigts.', 'A small amount on dry or slightly damp hair, style with a comb or your fingers.', 0, array['fine', 'thick']::text[], '{}'::text[], false, array['shine', 'hold']::text[], 1, true);
insert into public.products (name, brand, benefit_fr, benefit_en, usage_fr, usage_en, price, hair_types, scalp_types, for_beard, effects, sort, active) values ('03 Flaming', 'Nishman', 'Pommade crémeuse et gélifiée au parfum de pastèque : tenue moyenne à forte avec un fini brillant.', 'Creamy, gel like pomade with a watermelon scent: medium to strong hold with a shiny finish.', 'Répartir dans les cheveux secs, travailler la forme au peigne.', 'Spread through dry hair, shape with a comb.', 0, array['thick', 'curly']::text[], '{}'::text[], false, array['shine', 'hold']::text[], 2, true);
insert into public.products (name, brand, benefit_fr, benefit_en, usage_fr, usage_en, price, hair_types, scalp_types, for_beard, effects, sort, active) values ('04 Rugby Tropical Mango', 'Nishman', 'Cire à l’eau à forte tenue, idéale pour les cheveux courts à mi longs.', 'Strong hold water based wax, ideal for short to medium length hair.', 'Chauffer entre les mains, appliquer sur cheveux secs puis coiffer.', 'Warm between your hands, apply to dry hair, then style.', 0, array['fine', 'thick']::text[], '{}'::text[], false, array['hold', 'shine']::text[], 3, true);
insert into public.products (name, brand, benefit_fr, benefit_en, usage_fr, usage_en, price, hair_types, scalp_types, for_beard, effects, sort, active) values ('08 Matte Look', 'Nishman', 'Cire au fini mat, parfum vanille : un style naturel qui tient toute la journée.', 'Matte finish wax with a vanilla scent: a natural look that lasts all day.', 'Une petite quantité sur cheveux secs, travailler du bout des doigts pour texturer.', 'A small amount on dry hair, work in with your fingertips to add texture.', 0, array['fine', 'thick']::text[], '{}'::text[], false, array['natural', 'hold']::text[], 4, true);
insert into public.products (name, brand, benefit_fr, benefit_en, usage_fr, usage_en, price, hair_types, scalp_types, for_beard, effects, sort, active) values ('M5 Pâte coiffante mate', 'Nishman', 'Pâte à texture mate et fixation forte, pensée pour les coiffures créatives.', 'Matte texture paste with strong hold, made for creative styles.', 'Émulsionner entre les paumes, appliquer sur cheveux secs et sculpter.', 'Rub between your palms, apply to dry hair and sculpt.', 0, array['thick', 'curly']::text[], '{}'::text[], false, array['hold', 'natural']::text[], 5, true);
insert into public.products (name, brand, benefit_fr, benefit_en, usage_fr, usage_en, price, hair_types, scalp_types, for_beard, effects, sort, active) values ('M1 Argan', 'Nishman', 'Pâte matifiante enrichie à l’huile d’argan : fini mat et cheveux nourris.', 'Mattifying paste enriched with argan oil: matte finish and nourished hair.', 'Appliquer sur cheveux secs, coiffer avec les doigts pour un effet naturel.', 'Apply to dry hair, style with your fingers for a natural effect.', 0, array['fine', 'thick', 'curly']::text[], '{}'::text[], false, array['natural', 'care']::text[], 6, true);
insert into public.products (name, brand, benefit_fr, benefit_en, usage_fr, usage_en, price, hair_types, scalp_types, for_beard, effects, sort, active) values ('P0 Light Control', 'Nishman', 'Poudre coiffante légère : volume instantané et fini mat, idéale pour les cheveux fins.', 'Light styling powder: instant volume and matte finish, ideal for fine hair.', 'Saupoudrer sur les racines sèches, puis travailler du bout des doigts.', 'Sprinkle on dry roots, then work in with your fingertips.', 0, array['fine']::text[], '{}'::text[], false, array['volume', 'natural']::text[], 7, true);
insert into public.products (name, brand, benefit_fr, benefit_en, usage_fr, usage_en, price, hair_types, scalp_types, for_beard, effects, sort, active) values ('S1 Spider Wax', 'Nishman', 'Cire fibreuse pour des mèches texturées et du volume, avec une tenue souple.', 'Fibrous wax for textured strands and volume, with a flexible hold.', 'Étirer la cire entre les doigts, appliquer mèche par mèche.', 'Stretch the wax between your fingers, apply strand by strand.', 0, array['fine', 'thick']::text[], '{}'::text[], false, array['volume', 'hold']::text[], 8, true);
insert into public.products (name, brand, benefit_fr, benefit_en, usage_fr, usage_en, price, hair_types, scalp_types, for_beard, effects, sort, active) values ('Cire barbe et moustache', 'Nishman', 'Discipline la barbe et sculpte la moustache, pour un contour net toute la journée.', 'Tames the beard and shapes the moustache for a sharp outline all day.', 'Chauffer une petite quantité entre les doigts, appliquer puis brosser ou peigner.', 'Warm a small amount between your fingers, apply, then brush or comb.', 0, '{}'::text[], '{}'::text[], true, array['hold', 'care']::text[], 9, true);
